package io.github.jesterportfolio.hearth.survival.platform;

import java.util.*;import java.util.concurrent.*;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.command.CommandSender;import org.bukkit.inventory.*;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.economy.EnchantStore;
import io.github.jesterportfolio.hearth.survival.SurvivalWorld;

/** 원본 슬롯 선택 GUI와 동일 실행 API를 사용하는 공통 관리자. */
public final class PlatformMenus implements Listener,AutoCloseable {
    private final PlatformRuntime p;private boolean closed;
    private record Input(Player player,Object token,java.util.function.Consumer<String> action){}
    private final Map<UUID,Input> inputs=new java.util.concurrent.ConcurrentHashMap<>();
    private final class Screen implements InventoryHolder {final Player player;final Object token;final long generation;final Inventory inventory;final Map<Integer,Runnable> actions=new HashMap<>();boolean admin,used;Screen(Player player,String title){this.player=player;token=p.rpg.runtime.sessionToken(player);generation=p.generation();inventory=Bukkit.createInventory(this,54,Component.text(title));}public Inventory getInventory(){return inventory;}}
    public PlatformMenus(PlatformRuntime p){this.p=p;Bukkit.getPluginManager().registerEvents(this,p.plugin);}
    private boolean current(Screen s){return !closed&&!s.used&&p.available(s.player)&&p.rpg.runtime.current(s.player,s.token)&&p.generation()==s.generation&&s.player.getOpenInventory().getTopInventory()==s.inventory&&(!s.admin||s.player.hasPermission("hearth.platform.admin"));}
    private void button(Screen s,int slot,Material material,String title,List<String> lore,Runnable action){var item=new ItemStack(material);item.editMeta(meta->{meta.displayName(Component.text(title));meta.lore(lore.stream().map(Component::text).toList());});s.inventory.setItem(slot,item);if(action!=null)s.actions.put(slot,action);}
    private void show(Screen s){if(p.available(s.player)&&(!s.admin||s.player.hasPermission("hearth.platform.admin")))s.player.openInventory(s.inventory);}
    private void error(CommandSender sender,Throwable error){sender.sendMessage(Component.text("요청 거부/보류: "+io.github.jesterportfolio.hearth.inventory.InventorySaveSession.code(error)));}
    private void result(CommandSender sender,CompletionStage<?> work){work.whenCompleteAsync((v,e)->{if(e!=null)error(sender,e);else sender.sendMessage(Component.text("플랫폼 요청을 처리했습니다."));},p.owner);}
    public void command(CommandSender sender,String[] args)throws Exception{
        if(args.length==0){if(sender instanceof Player player)main(player);else p.status().forEach(sender::sendMessage);return;}
        if(args[0].equals("stats")&&args.length==1&&sender instanceof Player player){player.sendMessage(Component.text("능력치 출처="+p.rpg.aura.statLedger.view(player.getUniqueId())));return;}
        if(args[0].equals("sell")&&args.length==1&&sender instanceof Player player){p.autosell(player);return;}
        if(!sender.hasPermission("hearth.platform.admin"))throw new IllegalStateException("PLATFORM_PERMISSION");
        switch(args[0]){
            case "admin"->{if(sender instanceof Player player)admin(player);}
            case "status"->p.status().forEach(sender::sendMessage);
            case "reload"->{p.reload();sender.sendMessage("플랫폼 설정 리로드 완료");}
            case "stats"->{var player=Objects.requireNonNull(Bukkit.getPlayerExact(args[1]));sender.sendMessage("효과 출처="+p.rpg.aura.statLedger.view(player.getUniqueId()));}
            case "give-protection"->result(sender,p.protection(Objects.requireNonNull(Bukkit.getPlayerExact(args[1]))));
            case "history"->result(sender,p.store.configHistory().thenAcceptAsync(rows->rows.forEach(sender::sendMessage),p.owner));
            case "config-stage"->{var plan=p.changes.stage(args[1],args[2],p::validateCandidate);sender.sendMessage("후보="+plan.id()+" 대상="+plan.name()+" before="+plan.before()+" after="+plan.after()+" restart="+plan.restart());}
            case "config-apply"->result(sender,p.apply(UUID.fromString(args[1]),false));
            case "config-rollback"->result(sender,p.apply(UUID.fromString(args[1]),true));
            case "reset-list"->result(sender,p.resources.inspect().thenAcceptAsync(rows->rows.forEach(row->sender.sendMessage(row.toString())),p.owner));
            case "reset"->result(sender,p.resources.reset(SurvivalWorld.id(args[1]),Long.parseLong(args[2])));
            case "reset-resume"->result(sender,p.resources.resume(UUID.fromString(args[1])));
            case "reset-abort"->result(sender,p.resources.abort(UUID.fromString(args[1])));
            case "verify"->{var phase=args[1];io.github.jesterportfolio.hearth.verification.PlatformVerification.run(p,phase).whenCompleteAsync((v,e)->p.plugin.getLogger().log(e==null?java.util.logging.Level.INFO:java.util.logging.Level.SEVERE,"HEARTH_PLATFORM_PROBE "+(e==null?"PASS ":"FAIL ")+phase,e),p.owner);}
            default->sender.sendMessage("/플랫폼 admin|status|reload|stats [이름]|give-protection <이름>|history|config-stage <정본 파일> <이름.candidate>|config-apply <UUID>|config-rollback <UUID>|reset <자원 role> <seed>|reset-resume <UUID>|reset-abort <UUID>");
        }
    }
    public void main(Player player){if(!p.available(player)){player.sendMessage(Component.text("플랫폼·접속·거래 준비를 확인하세요."));return;}var s=new Screen(player,"Hearth 플랫폼");button(s,20,Material.ANVIL,"장비 강화",List.of("현재 강화 기능="+p.settings().upgrade()),()->equipment(player));button(s,22,Material.EMERALD,"자동 판매",List.of("설정된 일반 상품만 기존 상점에 판매","특수/강화/PDC 아이템 제외"),()->autosell(player));button(s,24,Material.BOOK,"장비 작업 기록",List.of("인챈트·강화 PG 확정 기록"),()->{var token=p.rpg.runtime.sessionToken(player);new EnchantStore(p.rpg.runtime.economy().database(),p.rpg.runtime.economy().store).history(p.rpg.runtime.economy().context(player)).whenCompleteAsync((rows,e)->{if(!p.rpg.runtime.current(player,token))return;if(e!=null)error(player,e);else rows.forEach(row->player.sendMessage(Component.text(row)));},p.owner);});if(player.hasPermission("hearth.platform.admin"))button(s,49,Material.COMPARATOR,"플랫폼 관리자",List.of(),()->admin(player));show(s);}
    private void equipment(Player player){var s=new Screen(player,"강화할 장비 선택");for(int i=0;i<41;i++){final int slot=i;var item=player.getInventory().getItem(i);if(item==null||item.isEmpty())continue;s.inventory.setItem(i,item.clone());s.actions.put(i,()->protection(player,slot,-1));}show(s);}
    private void protection(Player player,int gear,int chosen){var s=new Screen(player,"강화 보호 선택");for(int i=0;i<41;i++){final int slot=i;if(i!=gear&&EquipmentData.protection(player.getInventory().getItem(i))){s.inventory.setItem(i,player.getInventory().getItem(i).clone());s.actions.put(i,()->protection(player,gear,slot));}}button(s,49,Material.LIME_DYE,"확률·비용 확인",List.of("보호 슬롯="+chosen),()->confirm(player,gear,chosen));show(s);}
    private void confirm(Player player,int gear,int protection){var before=p.rpg.runtime.economy().capture(player);int level=EquipmentData.level(player.getInventory().getItem(gear))+1;var settings=p.settings();var vars=Map.of("level",(double)level);var s=new Screen(player,"강화 최종 확인");UUID request=UUID.randomUUID();button(s,22,Material.ANVIL,"강화 +"+level,List.of("성공률="+(settings.chance().evaluate(vars)*100)+"%","비용="+settings.cost().evaluate(vars),"재료="+settings.materials(),"실패="+settings.failure()+" 보호="+(protection>=0),"기존 인챈트/외부 메타데이터 보존","요청="+request),null);button(s,30,Material.LIME_DYE,"확정",List.of(),()->{s.used=true;player.closeInventory();result(player,p.upgrade(player,request,gear,protection,s.generation,before));});button(s,32,Material.BARRIER,"취소",List.of(),player::closeInventory);show(s);}
    private void autosell(Player player){autosell(player,0);}
    private void autosell(Player player,int page){var s=new Screen(player,"자동 판매 설정");var pref=p.preference(player.getUniqueId());button(s,4,Material.LEVER,"개인 자동 판매="+pref.enabled(),List.of("서버 기능="+p.settings().autosell()),()->result(player,p.preference(player,!pref.enabled(),pref.goods()).thenRunAsync(()->autosell(player),p.owner)));int slot=9;var goods=new ArrayList<>(new TreeSet<>(p.settings().goods()));for(String good:goods.subList(Math.min(page*36,goods.size()),Math.min((page+1)*36,goods.size()))){var definition=p.rpg.runtime.economy().content.goods().get(good);button(s,slot++,Material.valueOf(definition.material()),good,List.of("판매 허용="+pref.goods().contains(good)),()->{var next=new HashSet<>(pref.goods());if(!next.add(good))next.remove(good);result(player,p.preference(player,pref.enabled(),next).thenRunAsync(()->autosell(player),p.owner));});}if(page>0)button(s,45,Material.ARROW,"이전 상품",List.of(),()->autosell(player,page-1));if((page+1)*36<goods.size())button(s,53,Material.ARROW,"다음 상품",List.of(),()->autosell(player,page+1));button(s,49,Material.EMERALD,"지금 검사",List.of("커서/다른 창을 닫은 뒤 일반 소지품만 처리"),()->{player.closeInventory();Bukkit.getScheduler().runTask(p.plugin,()->p.autosell(player));});show(s);}
    public void admin(Player player){var s=new Screen(player,"플랫폼 관리자");s.admin=true;button(s,4,Material.COMPARATOR,"상태·성능",p.status(),()->p.status().forEach(line->player.sendMessage(Component.text(line))));button(s,20,Material.REDSTONE,"안전 리로드",List.of("platform.properties 검증 후 교체"),()->{try{p.reload();admin(player);}catch(Exception e){error(player,e);}});button(s,22,Material.PAPER,"설정 변경 후보",List.of("채팅: 정본파일 이름.candidate","후보·원본·해시 보존 후 명시적 적용"),()->ask(player,text->{try{String[] a=text.split(" ");var plan=p.changes.stage(a[0],a[1],p::validateCandidate);player.sendMessage(Component.text("후보 "+plan));}catch(Exception e){error(player,e);}}));button(s,24,Material.BOOK,"변경 적용/롤백",List.of("채팅: apply UUID 또는 rollback UUID"),()->ask(player,text->{String[] a=text.split(" ");if(!Set.of("apply","rollback").contains(a[0]))throw new IllegalArgumentException("CONFIG_ACTION");result(player,p.apply(UUID.fromString(a[1]),a[0].equals("rollback")));}));int slot=36;for(var row:p.resources.pending()){button(s,slot++,Material.CLOCK,row.request().toString(),List.of(row.role()+" "+row.phase(),"클릭: 준비 확정된 세대 재개"),()->result(player,p.resources.resume(row.request())));if(slot>=45)break;}show(s);}
    private void ask(Player player,java.util.function.Consumer<String> action){inputs.put(player.getUniqueId(),new Input(player,p.rpg.runtime.sessionToken(player),action));player.closeInventory();player.sendMessage(Component.text("관리 입력 · 취소 cancel"));}
    @EventHandler(priority=EventPriority.LOWEST) public void chat(AsyncPlayerChatEvent e){var input=inputs.remove(e.getPlayer().getUniqueId());if(input==null)return;e.setCancelled(true);String text=e.getMessage();if(text.equalsIgnoreCase("cancel")||text.length()>512)return;Bukkit.getScheduler().runTask(p.plugin,()->{if(input.player().hasPermission("hearth.platform.admin")&&p.rpg.runtime.current(input.player(),input.token()))try{input.action().accept(text);}catch(Exception error){error(input.player(),error);}});}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof PlatformMenus.Screen s))return;boolean denied=e.isCancelled();e.setCancelled(true);if(denied||e.getWhoClicked()!=s.player||!current(s)||e.getClickedInventory()!=s.inventory||e.getClick()!=ClickType.LEFT||!s.player.getItemOnCursor().isEmpty())return;var action=s.actions.get(e.getSlot());if(action!=null)Bukkit.getScheduler().runTask(p.plugin,()->{if(current(s))try{action.run();}catch(Exception error){error(s.player,error);}});}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof PlatformMenus.Screen)e.setCancelled(true);}
    @EventHandler public void quit(PlayerQuitEvent e){inputs.remove(e.getPlayer().getUniqueId());}
    public void close(){closed=true;inputs.clear();HandlerList.unregisterAll(this);}
}
